package com.ruoyi.framework.audit;
import ch.qos.logback.core.encoder.EncoderBase;import ch.qos.logback.classic.spi.ILoggingEvent;import ch.qos.logback.classic.spi.ThrowableProxyUtil;import java.util.*;import java.time.*;import java.nio.charset.StandardCharsets;import com.alibaba.fastjson2.JSON;
public class AuditJsonEncoder extends EncoderBase<ILoggingEvent>{public byte[] headerBytes(){return null;}public byte[] footerBytes(){return null;}public byte[] encode(ILoggingEvent e){Map<String,Object> row=new LinkedHashMap<>();row.put("eventId",UUID.randomUUID().toString());row.put("time",LocalDateTime.ofInstant(Instant.ofEpochMilli(e.getTimeStamp()),ZoneId.of("Asia/Shanghai")).toString());row.put("level",e.getLevel().toString());row.put("service","precious-metal");row.put("thread",e.getThreadName());row.put("traceId",e.getMDCPropertyMap().get("traceId"));row.put("component",e.getLoggerName());row.put("summary",limit(AuditRedactor.text(e.getFormattedMessage()),4096));row.put("exceptionClass",e.getThrowableProxy()==null?null:e.getThrowableProxy().getClassName());row.put("stack",e.getThrowableProxy()==null?null:limit(AuditRedactor.text(ThrowableProxyUtil.asString(e.getThrowableProxy())),32000));return (JSON.toJSONString(row)+"\n").getBytes(StandardCharsets.UTF_8);}private String limit(String s,int n){return s.substring(0,Math.min(s.length(),n));}}
